mkitem!{mkimpl!{impl < 'b , T : ? Sized > Ref < 'b , T > { # [doc = " Copies a `Ref`."] # [doc = ""] # [doc = " The `RefCell` is already immutably borrowed, so this cannot fail."] # [doc = ""] # [doc = " This is an associated function that needs to be used as"] # [doc = " `Ref::clone(...)`. A `Clone` implementation or a method would interfere"] # [doc = " with the widespread use of `r.borrow().clone()` to clone the contents of"] # [doc = " a `RefCell`."] # [stable (feature = "cell_extras" , since = "1.15.0")] # [must_use] # [inline] # [rustc_const_unstable (feature = "const_ref_cell" , issue = "137844")] pub const fn clone (orig : & Ref < 'b , T >) -> Ref < 'b , T > { Ref { value : orig . value , borrow : orig . borrow . clone () } } # [doc = " Makes a new `Ref` for a component of the borrowed data."] # [doc = ""] # [doc = " The `RefCell` is already immutably borrowed, so this cannot fail."] # [doc = ""] # [doc = " This is an associated function that needs to be used as `Ref::map(...)`."] # [doc = " A method would interfere with methods of the same name on the contents"] # [doc = " of a `RefCell` used through `Deref`."] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```"] # [doc = " use std::cell::{RefCell, Ref};"] # [doc = ""] # [doc = " let c = RefCell::new((5, 'b'));"] # [doc = " let b1: Ref<'_, (u32, char)> = c.borrow();"] # [doc = " let b2: Ref<'_, u32> = Ref::map(b1, |t| &t.0);"] # [doc = " assert_eq!(*b2, 5)"] # [doc = " ```"] # [stable (feature = "cell_map" , since = "1.8.0")] # [inline] pub fn map < U : ? Sized , F > (orig : Ref < 'b , T > , f : F) -> Ref < 'b , U > where F : FnOnce (& T) -> & U , { Ref { value : NonNull :: from (f (& * orig)) , borrow : orig . borrow } } # [doc = " Makes a new `Ref` for an optional component of the borrowed data. The"] # [doc = " original guard is returned as an `Err(..)` if the closure returns"] # [doc = " `None`."] # [doc = ""] # [doc = " The `RefCell` is already immutably borrowed, so this cannot fail."] # [doc = ""] # [doc = " This is an associated function that needs to be used as"] # [doc = " `Ref::filter_map(...)`. A method would interfere with methods of the same"] # [doc = " name on the contents of a `RefCell` used through `Deref`."] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```"] # [doc = " use std::cell::{RefCell, Ref};"] # [doc = ""] # [doc = " let c = RefCell::new(vec![1, 2, 3]);"] # [doc = " let b1: Ref<'_, Vec<u32>> = c.borrow();"] # [doc = " let b2: Result<Ref<'_, u32>, _> = Ref::filter_map(b1, |v| v.get(1));"] # [doc = " assert_eq!(*b2.unwrap(), 2);"] # [doc = " ```"] # [stable (feature = "cell_filter_map" , since = "1.63.0")] # [inline] pub fn filter_map < U : ? Sized , F > (orig : Ref < 'b , T > , f : F) -> Result < Ref < 'b , U > , Self > where F : FnOnce (& T) -> Option < & U > , { match f (& * orig) { Some (value) => Ok (Ref { value : NonNull :: from (value) , borrow : orig . borrow }) , None => Err (orig) , } } # [doc = " Tries to makes a new `Ref` for a component of the borrowed data."] # [doc = " On failure, the original guard is returned alongside with the error"] # [doc = " returned by the closure."] # [doc = ""] # [doc = " The `RefCell` is already immutably borrowed, so this cannot fail."] # [doc = ""] # [doc = " This is an associated function that needs to be used as"] # [doc = " `Ref::try_map(...)`. A method would interfere with methods of the same"] # [doc = " name on the contents of a `RefCell` used through `Deref`."] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```"] # [doc = " #![feature(refcell_try_map)]"] # [doc = " use std::cell::{RefCell, Ref};"] # [doc = " use std::str::{from_utf8, Utf8Error};"] # [doc = ""] # [doc = " let c = RefCell::new(vec![0xF0, 0x9F, 0xA6 ,0x80]);"] # [doc = " let b1: Ref<'_, Vec<u8>> = c.borrow();"] # [doc = " let b2: Result<Ref<'_, str>, _> = Ref::try_map(b1, |v| from_utf8(v));"] # [doc = " assert_eq!(&*b2.unwrap(), \"🦀\");"] # [doc = ""] # [doc = " let c = RefCell::new(vec![0xF0, 0x9F, 0xA6]);"] # [doc = " let b1: Ref<'_, Vec<u8>> = c.borrow();"] # [doc = " let b2: Result<_, (Ref<'_, Vec<u8>>, Utf8Error)> = Ref::try_map(b1, |v| from_utf8(v));"] # [doc = " let (b3, e) = b2.unwrap_err();"] # [doc = " assert_eq!(*b3, vec![0xF0, 0x9F, 0xA6]);"] # [doc = " assert_eq!(e.valid_up_to(), 0);"] # [doc = " ```"] # [unstable (feature = "refcell_try_map" , issue = "143801")] # [inline] pub fn try_map < U : ? Sized , E > (orig : Ref < 'b , T > , f : impl FnOnce (& T) -> Result < & U , E > ,) -> Result < Ref < 'b , U > , (Self , E) > { match f (& * orig) { Ok (value) => Ok (Ref { value : NonNull :: from (value) , borrow : orig . borrow }) , Err (e) => Err ((orig , e)) , } } # [doc = " Splits a `Ref` into multiple `Ref`s for different components of the"] # [doc = " borrowed data."] # [doc = ""] # [doc = " The `RefCell` is already immutably borrowed, so this cannot fail."] # [doc = ""] # [doc = " This is an associated function that needs to be used as"] # [doc = " `Ref::map_split(...)`. A method would interfere with methods of the same"] # [doc = " name on the contents of a `RefCell` used through `Deref`."] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```"] # [doc = " use std::cell::{Ref, RefCell};"] # [doc = ""] # [doc = " let cell = RefCell::new([1, 2, 3, 4]);"] # [doc = " let borrow = cell.borrow();"] # [doc = " let (begin, end) = Ref::map_split(borrow, |slice| slice.split_at(2));"] # [doc = " assert_eq!(*begin, [1, 2]);"] # [doc = " assert_eq!(*end, [3, 4]);"] # [doc = " ```"] # [stable (feature = "refcell_map_split" , since = "1.35.0")] # [inline] pub fn map_split < U : ? Sized , V : ? Sized , F > (orig : Ref < 'b , T > , f : F) -> (Ref < 'b , U > , Ref < 'b , V >) where F : FnOnce (& T) -> (& U , & V) , { let (a , b) = f (& * orig) ; let borrow = orig . borrow . clone () ; (Ref { value : NonNull :: from (a) , borrow } , Ref { value : NonNull :: from (b) , borrow : orig . borrow } ,) } # [doc = " Converts into a reference to the underlying data."] # [doc = ""] # [doc = " The underlying `RefCell` can never be mutably borrowed from again and will always appear"] # [doc = " already immutably borrowed. It is not a good idea to leak more than a constant number of"] # [doc = " references. The `RefCell` can be immutably borrowed again if only a smaller number of leaks"] # [doc = " have occurred in total."] # [doc = ""] # [doc = " This is an associated function that needs to be used as"] # [doc = " `Ref::leak(...)`. A method would interfere with methods of the"] # [doc = " same name on the contents of a `RefCell` used through `Deref`."] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```"] # [doc = " #![feature(cell_leak)]"] # [doc = " use std::cell::{RefCell, Ref};"] # [doc = " let cell = RefCell::new(0);"] # [doc = ""] # [doc = " let value = Ref::leak(cell.borrow());"] # [doc = " assert_eq!(*value, 0);"] # [doc = ""] # [doc = " assert!(cell.try_borrow().is_ok());"] # [doc = " assert!(cell.try_borrow_mut().is_err());"] # [doc = " ```"] # [unstable (feature = "cell_leak" , issue = "69099")] # [rustc_const_unstable (feature = "const_ref_cell" , issue = "137844")] pub const fn leak (orig : Ref < 'b , T >) -> & 'b T { mem :: forget (orig . borrow) ; unsafe { orig . value . as_ref () } } }}}
