mkitem!{mkimpl!{impl < 'b , T : ? Sized > RefMut < 'b , T > { # [doc = " Makes a new `RefMut` for a component of the borrowed data, e.g., an enum"] # [doc = " variant."] # [doc = ""] # [doc = " The `RefCell` is already mutably borrowed, so this cannot fail."] # [doc = ""] # [doc = " This is an associated function that needs to be used as"] # [doc = " `RefMut::map(...)`. A method would interfere with methods of the same"] # [doc = " name on the contents of a `RefCell` used through `Deref`."] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```"] # [doc = " use std::cell::{RefCell, RefMut};"] # [doc = ""] # [doc = " let c = RefCell::new((5, 'b'));"] # [doc = " {"] # [doc = "     let b1: RefMut<'_, (u32, char)> = c.borrow_mut();"] # [doc = "     let mut b2: RefMut<'_, u32> = RefMut::map(b1, |t| &mut t.0);"] # [doc = "     assert_eq!(*b2, 5);"] # [doc = "     *b2 = 42;"] # [doc = " }"] # [doc = " assert_eq!(*c.borrow(), (42, 'b'));"] # [doc = " ```"] # [stable (feature = "cell_map" , since = "1.8.0")] # [inline] pub fn map < U : ? Sized , F > (mut orig : RefMut < 'b , T > , f : F) -> RefMut < 'b , U > where F : FnOnce (& mut T) -> & mut U , { let value = NonNull :: from (f (& mut * orig)) ; RefMut { value , borrow : orig . borrow , marker : PhantomData } } # [doc = " Makes a new `RefMut` for an optional component of the borrowed data. The"] # [doc = " original guard is returned as an `Err(..)` if the closure returns"] # [doc = " `None`."] # [doc = ""] # [doc = " The `RefCell` is already mutably borrowed, so this cannot fail."] # [doc = ""] # [doc = " This is an associated function that needs to be used as"] # [doc = " `RefMut::filter_map(...)`. A method would interfere with methods of the"] # [doc = " same name on the contents of a `RefCell` used through `Deref`."] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```"] # [doc = " use std::cell::{RefCell, RefMut};"] # [doc = ""] # [doc = " let c = RefCell::new(vec![1, 2, 3]);"] # [doc = ""] # [doc = " {"] # [doc = "     let b1: RefMut<'_, Vec<u32>> = c.borrow_mut();"] # [doc = "     let mut b2: Result<RefMut<'_, u32>, _> = RefMut::filter_map(b1, |v| v.get_mut(1));"] # [doc = ""] # [doc = "     if let Ok(mut b2) = b2 {"] # [doc = "         *b2 += 2;"] # [doc = "     }"] # [doc = " }"] # [doc = ""] # [doc = " assert_eq!(*c.borrow(), vec![1, 4, 3]);"] # [doc = " ```"] # [stable (feature = "cell_filter_map" , since = "1.63.0")] # [inline] pub fn filter_map < U : ? Sized , F > (mut orig : RefMut < 'b , T > , f : F) -> Result < RefMut < 'b , U > , Self > where F : FnOnce (& mut T) -> Option < & mut U > , { match f (& mut * orig) { Some (value) => { Ok (RefMut { value : NonNull :: from (value) , borrow : orig . borrow , marker : PhantomData }) } None => Err (orig) , } } # [doc = " Tries to makes a new `RefMut` for a component of the borrowed data."] # [doc = " On failure, the original guard is returned alongside with the error"] # [doc = " returned by the closure."] # [doc = ""] # [doc = " The `RefCell` is already mutably borrowed, so this cannot fail."] # [doc = ""] # [doc = " This is an associated function that needs to be used as"] # [doc = " `RefMut::try_map(...)`. A method would interfere with methods of the same"] # [doc = " name on the contents of a `RefCell` used through `Deref`."] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```"] # [doc = " #![feature(refcell_try_map)]"] # [doc = " use std::cell::{RefCell, RefMut};"] # [doc = " use std::str::{from_utf8_mut, Utf8Error};"] # [doc = ""] # [doc = " let c = RefCell::new(vec![0x68, 0x65, 0x6C, 0x6C, 0x6F]);"] # [doc = " {"] # [doc = "     let b1: RefMut<'_, Vec<u8>> = c.borrow_mut();"] # [doc = "     let b2: Result<RefMut<'_, str>, _> = RefMut::try_map(b1, |v| from_utf8_mut(v));"] # [doc = "     let mut b2 = b2.unwrap();"] # [doc = "     assert_eq!(&*b2, \"hello\");"] # [doc = "     b2.make_ascii_uppercase();"] # [doc = " }"] # [doc = " assert_eq!(*c.borrow(), \"HELLO\".as_bytes());"] # [doc = ""] # [doc = " let c = RefCell::new(vec![0xFF]);"] # [doc = " let b1: RefMut<'_, Vec<u8>> = c.borrow_mut();"] # [doc = " let b2: Result<_, (RefMut<'_, Vec<u8>>, Utf8Error)> = RefMut::try_map(b1, |v| from_utf8_mut(v));"] # [doc = " let (b3, e) = b2.unwrap_err();"] # [doc = " assert_eq!(*b3, vec![0xFF]);"] # [doc = " assert_eq!(e.valid_up_to(), 0);"] # [doc = " ```"] # [unstable (feature = "refcell_try_map" , issue = "143801")] # [inline] pub fn try_map < U : ? Sized , E > (mut orig : RefMut < 'b , T > , f : impl FnOnce (& mut T) -> Result < & mut U , E > ,) -> Result < RefMut < 'b , U > , (Self , E) > { match f (& mut * orig) { Ok (value) => { Ok (RefMut { value : NonNull :: from (value) , borrow : orig . borrow , marker : PhantomData }) } Err (e) => Err ((orig , e)) , } } # [doc = " Splits a `RefMut` into multiple `RefMut`s for different components of the"] # [doc = " borrowed data."] # [doc = ""] # [doc = " The underlying `RefCell` will remain mutably borrowed until both"] # [doc = " returned `RefMut`s go out of scope."] # [doc = ""] # [doc = " The `RefCell` is already mutably borrowed, so this cannot fail."] # [doc = ""] # [doc = " This is an associated function that needs to be used as"] # [doc = " `RefMut::map_split(...)`. A method would interfere with methods of the"] # [doc = " same name on the contents of a `RefCell` used through `Deref`."] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```"] # [doc = " use std::cell::{RefCell, RefMut};"] # [doc = ""] # [doc = " let cell = RefCell::new([1, 2, 3, 4]);"] # [doc = " let borrow = cell.borrow_mut();"] # [doc = " let (mut begin, mut end) = RefMut::map_split(borrow, |slice| slice.split_at_mut(2));"] # [doc = " assert_eq!(*begin, [1, 2]);"] # [doc = " assert_eq!(*end, [3, 4]);"] # [doc = " begin.copy_from_slice(&[4, 3]);"] # [doc = " end.copy_from_slice(&[2, 1]);"] # [doc = " ```"] # [stable (feature = "refcell_map_split" , since = "1.35.0")] # [inline] pub fn map_split < U : ? Sized , V : ? Sized , F > (mut orig : RefMut < 'b , T > , f : F ,) -> (RefMut < 'b , U > , RefMut < 'b , V >) where F : FnOnce (& mut T) -> (& mut U , & mut V) , { let borrow = orig . borrow . clone () ; let (a , b) = f (& mut * orig) ; (RefMut { value : NonNull :: from (a) , borrow , marker : PhantomData } , RefMut { value : NonNull :: from (b) , borrow : orig . borrow , marker : PhantomData } ,) } # [doc = " Converts into a mutable reference to the underlying data."] # [doc = ""] # [doc = " The underlying `RefCell` can not be borrowed from again and will always appear already"] # [doc = " mutably borrowed, making the returned reference the only to the interior."] # [doc = ""] # [doc = " This is an associated function that needs to be used as"] # [doc = " `RefMut::leak(...)`. A method would interfere with methods of the"] # [doc = " same name on the contents of a `RefCell` used through `Deref`."] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```"] # [doc = " #![feature(cell_leak)]"] # [doc = " use std::cell::{RefCell, RefMut};"] # [doc = " let cell = RefCell::new(0);"] # [doc = ""] # [doc = " let value = RefMut::leak(cell.borrow_mut());"] # [doc = " assert_eq!(*value, 0);"] # [doc = " *value = 1;"] # [doc = ""] # [doc = " assert!(cell.try_borrow_mut().is_err());"] # [doc = " ```"] # [unstable (feature = "cell_leak" , issue = "69099")] # [rustc_const_unstable (feature = "const_ref_cell" , issue = "137844")] pub const fn leak (mut orig : RefMut < 'b , T >) -> & 'b mut T { mem :: forget (orig . borrow) ; unsafe { orig . value . as_mut () } } }}}
