mkitem!{mkimpl!{impl < 'b > BorrowRefMut < 'b > { # [inline] const fn new (borrow : & 'b Cell < BorrowCounter >) -> Option < BorrowRefMut < 'b > > { match borrow . get () { UNUSED => { borrow . replace (UNUSED - 1) ; Some (BorrowRefMut { borrow }) } _ => None , } } # [inline] fn clone (& self) -> BorrowRefMut < 'b > { let borrow = self . borrow . get () ; debug_assert ! (is_writing (borrow)) ; assert ! (borrow != BorrowCounter :: MIN) ; self . borrow . set (borrow - 1) ; BorrowRefMut { borrow : self . borrow } } }}}
