mkitem!{mkstruct!{# [doc = " The core primitive for interior mutability in Rust."] # [doc = ""] # [doc = " If you have a reference `&T`, then normally in Rust the compiler performs optimizations based on"] # [doc = " the knowledge that `&T` points to immutable data. Mutating that data, for example through an"] # [doc = " alias or by transmuting a `&T` into a `&mut T`, is considered undefined behavior."] # [doc = " `UnsafeCell<T>` opts-out of the immutability guarantee for `&T`: a shared reference"] # [doc = " `&UnsafeCell<T>` may point to data that is being mutated. This is called \"interior mutability\"."] # [doc = ""] # [doc = " All other types that allow internal mutability, such as [`Cell<T>`] and [`RefCell<T>`], internally"] # [doc = " use `UnsafeCell` to wrap their data."] # [doc = ""] # [doc = " Note that only the immutability guarantee for shared references is affected by `UnsafeCell`. The"] # [doc = " uniqueness guarantee for mutable references is unaffected. There is *no* legal way to obtain"] # [doc = " aliasing `&mut`, not even with `UnsafeCell<T>`."] # [doc = ""] # [doc = " `UnsafeCell` does nothing to avoid data races; they are still undefined behavior. If multiple"] # [doc = " threads have access to the same `UnsafeCell`, they must follow the usual rules of the"] # [doc = " [concurrent memory model]: conflicting non-synchronized accesses must be done via the APIs in"] # [doc = " [`core::sync::atomic`]."] # [doc = ""] # [doc = " The `UnsafeCell` API itself is technically very simple: [`.get()`] gives you a raw pointer"] # [doc = " `*mut T` to its contents. It is up to _you_ as the abstraction designer to use that raw pointer"] # [doc = " correctly."] # [doc = ""] # [doc = " [`.get()`]: `UnsafeCell::get`"] # [doc = " [concurrent memory model]: ../sync/atomic/index.html#memory-model-for-atomic-accesses"] # [doc = ""] # [doc = " # Aliasing rules"] # [doc = ""] # [doc = " The precise Rust aliasing rules are somewhat in flux, but the main points are not contentious:"] # [doc = ""] # [doc = " - If you create a safe reference with lifetime `'a` (either a `&T` or `&mut T` reference), then"] # [doc = "   you must not access the data in any way that contradicts that reference for the remainder of"] # [doc = "   `'a`. For example, this means that if you take the `*mut T` from an `UnsafeCell<T>` and cast it"] # [doc = "   to an `&T`, then the data in `T` must remain immutable (modulo any `UnsafeCell` data found"] # [doc = "   within `T`, of course) until that reference's lifetime expires. Similarly, if you create a"] # [doc = "   `&mut T` reference that is released to safe code, then you must not access the data within the"] # [doc = "   `UnsafeCell` until that reference expires."] # [doc = ""] # [doc = " - For both `&T` without `UnsafeCell<_>` and `&mut T`, you must also not deallocate the data"] # [doc = "   until the reference expires. As a special exception, given an `&T`, any part of it that is"] # [doc = "   inside an `UnsafeCell<_>` may be deallocated during the lifetime of the reference, after the"] # [doc = "   last time the reference is used (dereferenced or reborrowed). Since you cannot deallocate a part"] # [doc = "   of what a reference points to, this means the memory an `&T` points to can be deallocated only if"] # [doc = "   *every part of it* (including padding) is inside an `UnsafeCell`."] # [doc = ""] # [doc = " However, whenever a `&UnsafeCell<T>` is constructed or dereferenced, it must still point to"] # [doc = " live memory and the compiler is allowed to insert spurious reads if it can prove that this"] # [doc = " memory has not yet been deallocated."] # [doc = ""] # [doc = " To assist with proper design, the following scenarios are explicitly declared legal"] # [doc = " for single-threaded code:"] # [doc = ""] # [doc = " 1. A `&T` reference can be released to safe code and there it can co-exist with other `&T`"] # [doc = "    references, but not with a `&mut T`"] # [doc = ""] # [doc = " 2. A `&mut T` reference may be released to safe code provided neither other `&mut T` nor `&T`"] # [doc = "    co-exist with it. A `&mut T` must always be unique."] # [doc = ""] # [doc = " Note that whilst mutating the contents of an `&UnsafeCell<T>` (even while other"] # [doc = " `&UnsafeCell<T>` references alias the cell) is"] # [doc = " ok (provided you enforce the above invariants some other way), it is still undefined behavior"] # [doc = " to have multiple `&mut UnsafeCell<T>` aliases. That is, `UnsafeCell` is a wrapper"] # [doc = " designed to have a special interaction with _shared_ accesses (_i.e._, through an"] # [doc = " `&UnsafeCell<_>` reference); there is no magic whatsoever when dealing with _exclusive_"] # [doc = " accesses (_e.g._, through a `&mut UnsafeCell<_>`): neither the cell nor the wrapped value"] # [doc = " may be aliased for the duration of that `&mut` borrow."] # [doc = " This is showcased by the [`.get_mut()`] accessor, which is a _safe_ getter that yields"] # [doc = " a `&mut T`."] # [doc = ""] # [doc = " [`.get_mut()`]: `UnsafeCell::get_mut`"] # [doc = ""] # [doc = " # Memory layout"] # [doc = ""] # [doc = " `UnsafeCell<T>` has the same in-memory representation as its inner type `T`. A consequence"] # [doc = " of this guarantee is that it is possible to convert between `T` and `UnsafeCell<T>`."] # [doc = " Special care has to be taken when converting a nested `T` inside of an `Outer<T>` type"] # [doc = " to an `Outer<UnsafeCell<T>>` type: this is not sound when the `Outer<T>` type enables [niche]"] # [doc = " optimizations. For example, the type `Option<NonNull<u8>>` is typically 8 bytes large on"] # [doc = " 64-bit platforms, but the type `Option<UnsafeCell<NonNull<u8>>>` takes up 16 bytes of space."] # [doc = " Therefore this is not a valid conversion, despite `NonNull<u8>` and `UnsafeCell<NonNull<u8>>>`"] # [doc = " having the same memory layout. This is because `UnsafeCell` disables niche optimizations in"] # [doc = " order to avoid its interior mutability property from spreading from `T` into the `Outer` type,"] # [doc = " thus this can cause distortions in the type size in these cases."] # [doc = ""] # [doc = " Note that the only valid way to obtain a `*mut T` pointer to the contents of a"] # [doc = " _shared_ `UnsafeCell<T>` is through [`.get()`]  or [`.raw_get()`]. A `&mut T` reference"] # [doc = " can be obtained by either dereferencing this pointer or by calling [`.get_mut()`]"] # [doc = " on an _exclusive_ `UnsafeCell<T>`. Even though `T` and `UnsafeCell<T>` have the"] # [doc = " same memory layout, the following is not allowed and undefined behavior:"] # [doc = ""] # [doc = " ```rust,compile_fail"] # [doc = " # use std::cell::UnsafeCell;"] # [doc = " unsafe fn not_allowed<T>(ptr: &UnsafeCell<T>) -> &mut T {"] # [doc = "   let t = ptr as *const UnsafeCell<T> as *mut T;"] # [doc = "   // This is undefined behavior, because the `*mut T` pointer"] # [doc = "   // was not obtained through `.get()` nor `.raw_get()`:"] # [doc = "   unsafe { &mut *t }"] # [doc = " }"] # [doc = " ```"] # [doc = ""] # [doc = " Instead, do this:"] # [doc = ""] # [doc = " ```rust"] # [doc = " # use std::cell::UnsafeCell;"] # [doc = " // Safety: the caller must ensure that there are no references that"] # [doc = " // point to the *contents* of the `UnsafeCell`."] # [doc = " unsafe fn get_mut<T>(ptr: &UnsafeCell<T>) -> &mut T {"] # [doc = "   unsafe { &mut *ptr.get() }"] # [doc = " }"] # [doc = " ```"] # [doc = ""] # [doc = " Converting in the other direction from a `&mut T`"] # [doc = " to an `&UnsafeCell<T>` is allowed:"] # [doc = ""] # [doc = " ```rust"] # [doc = " # use std::cell::UnsafeCell;"] # [doc = " fn get_shared<T>(ptr: &mut T) -> &UnsafeCell<T> {"] # [doc = "   let t = ptr as *mut T as *const UnsafeCell<T>;"] # [doc = "   // SAFETY: `T` and `UnsafeCell<T>` have the same memory layout"] # [doc = "   unsafe { &*t }"] # [doc = " }"] # [doc = " ```"] # [doc = ""] # [doc = " [niche]: https://rust-lang.github.io/unsafe-code-guidelines/glossary.html#niche"] # [doc = " [`.raw_get()`]: `UnsafeCell::raw_get`"] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " Here is an example showcasing how to soundly mutate the contents of an `UnsafeCell<_>` despite"] # [doc = " there being multiple references aliasing the cell:"] # [doc = ""] # [doc = " ```"] # [doc = " use std::cell::UnsafeCell;"] # [doc = ""] # [doc = " let x: UnsafeCell<i32> = 42.into();"] # [doc = " // Get multiple / concurrent / shared references to the same `x`."] # [doc = " let (p1, p2): (&UnsafeCell<i32>, &UnsafeCell<i32>) = (&x, &x);"] # [doc = ""] # [doc = " unsafe {"] # [doc = "     // SAFETY: within this scope there are no other references to `x`'s contents,"] # [doc = "     // so ours is effectively unique."] # [doc = "     let p1_exclusive: &mut i32 = &mut *p1.get(); // -- borrow --+"] # [doc = "     *p1_exclusive += 27; //                                     |"] # [doc = " } // <---------- cannot go beyond this point -------------------+"] # [doc = ""] # [doc = " unsafe {"] # [doc = "     // SAFETY: within this scope nobody expects to have exclusive access to `x`'s contents,"] # [doc = "     // so we can have multiple shared accesses concurrently."] # [doc = "     let p2_shared: &i32 = &*p2.get();"] # [doc = "     assert_eq!(*p2_shared, 42 + 27);"] # [doc = "     let p1_shared: &i32 = &*p1.get();"] # [doc = "     assert_eq!(*p1_shared, *p2_shared);"] # [doc = " }"] # [doc = " ```"] # [doc = ""] # [doc = " The following example showcases the fact that exclusive access to an `UnsafeCell<T>`"] # [doc = " implies exclusive access to its `T`:"] # [doc = ""] # [doc = " ```rust"] # [doc = " #![forbid(unsafe_code)]"] # [doc = " // with exclusive accesses, `UnsafeCell` is a transparent no-op wrapper, so no need for"] # [doc = " // `unsafe` here."] # [doc = " use std::cell::UnsafeCell;"] # [doc = ""] # [doc = " let mut x: UnsafeCell<i32> = 42.into();"] # [doc = ""] # [doc = " // Get a compile-time-checked unique reference to `x`."] # [doc = " let p_unique: &mut UnsafeCell<i32> = &mut x;"] # [doc = " // With an exclusive reference, we can mutate the contents for free."] # [doc = " *p_unique.get_mut() = 0;"] # [doc = " // Or, equivalently:"] # [doc = " x = UnsafeCell::new(0);"] # [doc = ""] # [doc = " // When we own the value, we can extract the contents for free."] # [doc = " let contents: i32 = x.into_inner();"] # [doc = " assert_eq!(contents, 0);"] # [doc = " ```"] # [lang = "unsafe_cell"] # [stable (feature = "rust1" , since = "1.0.0")] # [repr (transparent)] # [rustc_pub_transparent] pub struct UnsafeCell < T : ? Sized > { value : T , }}}
