mkitem!{mkimpl!{impl < T > UnsafeCell < T > { # [doc = " Constructs a new instance of `UnsafeCell` which will wrap the specified"] # [doc = " value."] # [doc = ""] # [doc = " All access to the inner value through `&UnsafeCell<T>` requires `unsafe` code."] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```"] # [doc = " use std::cell::UnsafeCell;"] # [doc = ""] # [doc = " let uc = UnsafeCell::new(5);"] # [doc = " ```"] # [stable (feature = "rust1" , since = "1.0.0")] # [rustc_const_stable (feature = "const_unsafe_cell_new" , since = "1.32.0")] # [inline (always)] pub const fn new (value : T) -> UnsafeCell < T > { UnsafeCell { value } } # [doc = " Unwraps the value, consuming the cell."] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```"] # [doc = " use std::cell::UnsafeCell;"] # [doc = ""] # [doc = " let uc = UnsafeCell::new(5);"] # [doc = ""] # [doc = " let five = uc.into_inner();"] # [doc = " ```"] # [inline (always)] # [stable (feature = "rust1" , since = "1.0.0")] # [rustc_const_stable (feature = "const_cell_into_inner" , since = "1.83.0")] # [rustc_allow_const_fn_unstable (const_precise_live_drops)] pub const fn into_inner (self) -> T { self . value } # [doc = " Replace the value in this `UnsafeCell` and return the old value."] # [doc = ""] # [doc = " # Safety"] # [doc = ""] # [doc = " The caller must take care to avoid aliasing and data races."] # [doc = ""] # [doc = " - It is Undefined Behavior to allow calls to race with"] # [doc = "   any other access to the wrapped value."] # [doc = " - It is Undefined Behavior to call this while any other"] # [doc = "   reference(s) to the wrapped value are alive."] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```"] # [doc = " #![feature(unsafe_cell_access)]"] # [doc = " use std::cell::UnsafeCell;"] # [doc = ""] # [doc = " let uc = UnsafeCell::new(5);"] # [doc = ""] # [doc = " let old = unsafe { uc.replace(10) };"] # [doc = " assert_eq!(old, 5);"] # [doc = " ```"] # [inline] # [unstable (feature = "unsafe_cell_access" , issue = "136327")] pub const unsafe fn replace (& self , value : T) -> T { unsafe { ptr :: replace (self . get () , value) } } }}}
mkitem!{mkimpl!{impl < T : ? Sized > UnsafeCell < T > { # [doc = " Converts from `&mut T` to `&mut UnsafeCell<T>`."] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```"] # [doc = " use std::cell::UnsafeCell;"] # [doc = ""] # [doc = " let mut val = 42;"] # [doc = " let uc = UnsafeCell::from_mut(&mut val);"] # [doc = ""] # [doc = " *uc.get_mut() -= 1;"] # [doc = " assert_eq!(*uc.get_mut(), 41);"] # [doc = " ```"] # [inline (always)] # [stable (feature = "unsafe_cell_from_mut" , since = "1.84.0")] # [rustc_const_stable (feature = "unsafe_cell_from_mut" , since = "1.84.0")] pub const fn from_mut (value : & mut T) -> & mut UnsafeCell < T > { unsafe { & mut * (value as * mut T as * mut UnsafeCell < T >) } } # [doc = " Gets a mutable pointer to the wrapped value."] # [doc = ""] # [doc = " This can be cast to a pointer of any kind. When creating references, you must uphold the"] # [doc = " aliasing rules; see [the type-level docs][UnsafeCell#aliasing-rules] for more discussion and"] # [doc = " caveats."] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```"] # [doc = " use std::cell::UnsafeCell;"] # [doc = ""] # [doc = " let uc = UnsafeCell::new(5);"] # [doc = ""] # [doc = " let five = uc.get();"] # [doc = " ```"] # [inline (always)] # [stable (feature = "rust1" , since = "1.0.0")] # [rustc_const_stable (feature = "const_unsafecell_get" , since = "1.32.0")] # [rustc_as_ptr] # [rustc_never_returns_null_ptr] pub const fn get (& self) -> * mut T { self as * const UnsafeCell < T > as * const T as * mut T } # [doc = " Returns a mutable reference to the underlying data."] # [doc = ""] # [doc = " This call borrows the `UnsafeCell` mutably (at compile-time) which"] # [doc = " guarantees that we possess the only reference."] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```"] # [doc = " use std::cell::UnsafeCell;"] # [doc = ""] # [doc = " let mut c = UnsafeCell::new(5);"] # [doc = " *c.get_mut() += 1;"] # [doc = ""] # [doc = " assert_eq!(*c.get_mut(), 6);"] # [doc = " ```"] # [inline (always)] # [stable (feature = "unsafe_cell_get_mut" , since = "1.50.0")] # [rustc_const_stable (feature = "const_unsafecell_get_mut" , since = "1.83.0")] pub const fn get_mut (& mut self) -> & mut T { & mut self . value } # [doc = " Gets a mutable pointer to the wrapped value."] # [doc = " The difference from [`get`] is that this function accepts a raw pointer,"] # [doc = " which is useful to avoid the creation of temporary references."] # [doc = ""] # [doc = " This can be cast to a pointer of any kind. When creating references, you must uphold the"] # [doc = " aliasing rules; see [the type-level docs][UnsafeCell#aliasing-rules] for more discussion and"] # [doc = " caveats."] # [doc = ""] # [doc = " [`get`]: UnsafeCell::get()"] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " Gradual initialization of an `UnsafeCell` requires `raw_get`, as"] # [doc = " calling `get` would require creating a reference to uninitialized data:"] # [doc = ""] # [doc = " ```"] # [doc = " use std::cell::UnsafeCell;"] # [doc = " use std::mem::MaybeUninit;"] # [doc = ""] # [doc = " let m = MaybeUninit::<UnsafeCell<i32>>::uninit();"] # [doc = " unsafe { UnsafeCell::raw_get(m.as_ptr()).write(5); }"] # [doc = " // avoid below which references to uninitialized data"] # [doc = " // unsafe { UnsafeCell::get(&*m.as_ptr()).write(5); }"] # [doc = " let uc = unsafe { m.assume_init() };"] # [doc = ""] # [doc = " assert_eq!(uc.into_inner(), 5);"] # [doc = " ```"] # [inline (always)] # [stable (feature = "unsafe_cell_raw_get" , since = "1.56.0")] # [rustc_const_stable (feature = "unsafe_cell_raw_get" , since = "1.56.0")] # [rustc_diagnostic_item = "unsafe_cell_raw_get"] pub const fn raw_get (this : * const Self) -> * mut T { this as * const T as * mut T } # [doc = " Get a shared reference to the value within the `UnsafeCell`."] # [doc = ""] # [doc = " # Safety"] # [doc = ""] # [doc = " - It is Undefined Behavior to call this while any mutable"] # [doc = "   reference to the wrapped value is alive."] # [doc = " - Mutating the wrapped value while the returned"] # [doc = "   reference is alive is Undefined Behavior."] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```"] # [doc = " #![feature(unsafe_cell_access)]"] # [doc = " use std::cell::UnsafeCell;"] # [doc = ""] # [doc = " let uc = UnsafeCell::new(5);"] # [doc = ""] # [doc = " let val = unsafe { uc.as_ref_unchecked() };"] # [doc = " assert_eq!(val, &5);"] # [doc = " ```"] # [inline] # [unstable (feature = "unsafe_cell_access" , issue = "136327")] pub const unsafe fn as_ref_unchecked (& self) -> & T { unsafe { self . get () . as_ref_unchecked () } } # [doc = " Get an exclusive reference to the value within the `UnsafeCell`."] # [doc = ""] # [doc = " # Safety"] # [doc = ""] # [doc = " - It is Undefined Behavior to call this while any other"] # [doc = "   reference(s) to the wrapped value are alive."] # [doc = " - Mutating the wrapped value through other means while the"] # [doc = "   returned reference is alive is Undefined Behavior."] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```"] # [doc = " #![feature(unsafe_cell_access)]"] # [doc = " use std::cell::UnsafeCell;"] # [doc = ""] # [doc = " let uc = UnsafeCell::new(5);"] # [doc = ""] # [doc = " unsafe { *uc.as_mut_unchecked() += 1; }"] # [doc = " assert_eq!(uc.into_inner(), 6);"] # [doc = " ```"] # [inline] # [unstable (feature = "unsafe_cell_access" , issue = "136327")] # [allow (clippy :: mut_from_ref)] pub const unsafe fn as_mut_unchecked (& self) -> & mut T { unsafe { self . get () . as_mut_unchecked () } } }}}
