macro_rules! assert_coerce_unsized_introspect {
    () => {
        emit_message!("📊 INTROSPECT: Function assert_coerce_unsized in module {}", module_path!());
    };
}

mkfn!{
    assert_coerce_unsized_introspect!();
    # [allow (unused)] fn assert_coerce_unsized (a : UnsafeCell < & i32 > , b : SyncUnsafeCell < & i32 > , c : Cell < & i32 > , d : RefCell < & i32 > ,) { let _ : UnsafeCell < & dyn Send > = a ; let _ : SyncUnsafeCell < & dyn Send > = b ; let _ : Cell < & dyn Send > = c ; let _ : RefCell < & dyn Send > = d ; }
}
